async function start(mode:'sales'|'production'='sales',view:'detail'|'matrix'='detail',selection:{productLineIds?:number[];productKeys?:string[]}={productLineIds:[51]}){const pinia=createPinia();setActivePinia(pinia);useUserStore().token='sales-test';useUserStore().profile={userId:1,userName:'工程师'} as never;localStorage.setItem(moldSalesPreferenceKey(1,mode),JSON.stringify({version:1,view,...selection}));const router=createRouter({history:createMemoryHistory(),routes:['/production-totals','/molds','/mold-applications'].map(path=>({path,component:{template:'<div/>'}}))});await router.push('/production-totals');await router.isReady();wrapper=mount(MoldSalesOverview,{props:{mode},global:{plugins:[pinia,router,ElementPlus],stubs:{Teleport:true,ElSelect:{props:['modelValue'],emits:['update:modelValue'],template:'<select :value="modelValue" @change="$emit(\'update:modelValue\',$event.target.value)"><slot/></select>'},ElOption:{props:['value','label'],template:'<option :value="value">{{label}}</option>'}}},attachTo:document.body});await flushPromises();return router}
beforeEach(()=>{vi.clearAllMocks();localStorage.clear();api.getMoldSalesOptions.mockResolvedValue({products:[{productLineId:51,productName:'亮甲 2.0',status:'active'}],brands:[{brandId:1,brandName:'Apple'}],defaultProductLineIds:[51]});api.getMoldSalesMatrix.mockResolvedValue({content:[{rowKey:'shared:1144',brandIds:[1],brandNames:['Apple'],phoneModelIds:[1,2],modelKind:'shared',modelNames:['iPhone 17 Pro / iPhone 18 Pro'],phoneCodes:['1144','1217'],totalSalesQuantity:3000,cells:[{productLineId:51,salesQuantity:3000,state:'historical',stateLabel:'历史销量',groupIds:[7],applicationIds:[],itemIds:[],registeredSets:0}]}],totalElements:1,totalSalesQuantity:3000,productTotals:[{productLineId:51,salesQuantity:3000}],status:page().status});api.getMoldSales.mockResolvedValue(page());api.getMoldSalesDetail.mockResolvedValue({group:row(),orders:[{sourceId:'x',orderNo:'CRM-1',name:'透明壳',quantity:1000,eligibility:'cancelled',orderStatus:'cancelled',itemCode:'NBA4030114402',date:'2026-10-10'}],totalElements:1,status:page().status})})
