 it('retains actual execution states while reducing generic pending labels in product detail',async()=>{const p=page();Object.assign(p.content[0],{coverageState:'paused',coverageLabel:'已暂停',unmapped:false});api.getMoldSales.mockResolvedValue(p);await start();expect(wrapper!.get('.coverage-label').text()).toBe('已暂停');expect(wrapper!.get('.quantity-link').text()).toContain('3,000')})
